-- lovable-cron-fallback-reviewed: Wake on enqueue and minute reconciliation only while native transfers remain, unschedule on drain; transaction receipts have no webhook; user informed of max 1440 checks/day and Cloud cost. Immediate callbacks process chunks between checks.
CREATE TABLE public.celo_batch_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_user_id uuid NOT NULL,client_id uuid NOT NULL,sender_address text NOT NULL,encrypted_key text,amount text NOT NULL,total integer NOT NULL CHECK(total BETWEEN 1 AND 10000),status text NOT NULL DEFAULT 'running' CHECK(status IN ('running','stopping','stopped','completed','failed')),lease_id uuid,lease_until timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,UNIQUE(owner_user_id,client_id));
GRANT SELECT(id,owner_user_id,client_id,sender_address,amount,total,status,last_error,created_at,finished_at) ON public.celo_batch_jobs TO authenticated; GRANT ALL ON public.celo_batch_jobs TO service_role; ALTER TABLE public.celo_batch_jobs ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read own CELO batches" ON public.celo_batch_jobs FOR SELECT TO authenticated USING(owner_user_id=auth.uid());
CREATE UNIQUE INDEX celo_batch_active_sender ON public.celo_batch_jobs(lower(sender_address)) WHERE status IN ('running','stopping');
CREATE TABLE public.celo_batch_chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES public.celo_batch_jobs(id),owner_user_id uuid NOT NULL,position integer NOT NULL,recipients jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirming','success','failed','cancelled')),signed_tx text,tx_hash text,error_message text,attempts integer NOT NULL DEFAULT 0,UNIQUE(job_id,position));
GRANT SELECT(id,job_id,owner_user_id,position,recipients,status,tx_hash,error_message) ON public.celo_batch_chunks TO authenticated; GRANT ALL ON public.celo_batch_chunks TO service_role; ALTER TABLE public.celo_batch_chunks ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read own CELO receivers" ON public.celo_batch_chunks FOR SELECT TO authenticated USING(owner_user_id=auth.uid());
CREATE FUNCTION public.create_celo_batch(p_owner uuid,p_client uuid,p_sender text,p_key text,p_amount text,p_recipients jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE jid uuid; n integer; BEGIN SELECT id INTO jid FROM public.celo_batch_jobs WHERE owner_user_id=p_owner AND client_id=p_client; IF jid IS NOT NULL THEN RETURN jid; END IF; n:=jsonb_array_length(p_recipients); IF n<1 OR n>10000 THEN RAISE EXCEPTION 'Invalid recipient count'; END IF; INSERT INTO public.celo_batch_jobs(owner_user_id,client_id,sender_address,encrypted_key,amount,total) VALUES(p_owner,p_client,p_sender,p_key,p_amount,n) RETURNING id INTO jid; INSERT INTO public.celo_batch_chunks(job_id,owner_user_id,position,recipients) SELECT jid,p_owner,((ord-1)/75)::integer,jsonb_agg(value ORDER BY ord) FROM jsonb_array_elements(p_recipients) WITH ORDINALITY AS x(value,ord) GROUP BY ((ord-1)/75)::integer; RETURN jid; END; $$;
REVOKE ALL ON FUNCTION public.create_celo_batch(uuid,uuid,text,text,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_celo_batch(uuid,uuid,text,text,text,jsonb) TO service_role;
CREATE FUNCTION public.reserve_celo_batch() RETURNS SETOF public.celo_batch_jobs LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN QUERY WITH picked AS (SELECT id FROM public.celo_batch_jobs WHERE status IN ('running','stopping') AND (lease_until IS NULL OR lease_until<now()) ORDER BY lease_until NULLS FIRST,created_at FOR UPDATE SKIP LOCKED LIMIT 1) UPDATE public.celo_batch_jobs j SET lease_id=gen_random_uuid(),lease_until=now()+interval '90 seconds' FROM picked WHERE j.id=picked.id RETURNING j.*; END; $$;
REVOKE ALL ON FUNCTION public.reserve_celo_batch() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reserve_celo_batch() TO service_role;
CREATE FUNCTION public.write_celo_chunk(p_job uuid,p_lease uuid,p_chunk uuid,p_patch jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.celo_batch_jobs; BEGIN SELECT * INTO j FROM public.celo_batch_jobs WHERE id=p_job AND lease_id=p_lease AND lease_until>now() FOR UPDATE; IF j.id IS NULL THEN RETURN false; END IF; IF j.status<>'running' AND p_patch ? 'signed_tx' AND p_patch->>'signed_tx' IS NOT NULL AND EXISTS(SELECT 1 FROM public.celo_batch_chunks WHERE id=p_chunk AND signed_tx IS NULL) THEN RETURN false; END IF; UPDATE public.celo_batch_chunks SET status=coalesce(p_patch->>'status',status),signed_tx=CASE WHEN p_patch ? 'signed_tx' THEN p_patch->>'signed_tx' ELSE signed_tx END,tx_hash=coalesce(p_patch->>'tx_hash',tx_hash),error_message=CASE WHEN p_patch ? 'error_message' THEN p_patch->>'error_message' ELSE error_message END,attempts=attempts+1 WHERE id=p_chunk AND job_id=p_job; RETURN FOUND; END; $$;
REVOKE ALL ON FUNCTION public.write_celo_chunk(uuid,uuid,uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.write_celo_chunk(uuid,uuid,uuid,jsonb) TO service_role;
CREATE FUNCTION public.stop_celo_batch(p_job uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.celo_batch_jobs SET status='stopping' WHERE id=p_job AND owner_user_id=auth.uid() AND status='running'; RETURN FOUND; END; $$; REVOKE ALL ON FUNCTION public.stop_celo_batch(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.stop_celo_batch(uuid) TO authenticated;
CREATE FUNCTION public.finish_celo_batch(p_job uuid,p_lease uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.celo_batch_jobs; remaining boolean; BEGIN SELECT * INTO j FROM public.celo_batch_jobs WHERE id=p_job AND lease_id=p_lease FOR UPDATE; IF j.id IS NULL THEN RETURN false; END IF; IF j.status='stopping' THEN UPDATE public.celo_batch_chunks SET status='cancelled' WHERE job_id=p_job AND status='pending' AND signed_tx IS NULL; END IF; SELECT EXISTS(SELECT 1 FROM public.celo_batch_chunks WHERE job_id=p_job AND status IN ('pending','confirming')) INTO remaining; UPDATE public.celo_batch_jobs SET status=CASE WHEN remaining THEN status WHEN status='stopping' THEN 'stopped' ELSE 'completed' END,encrypted_key=CASE WHEN remaining THEN encrypted_key ELSE NULL END,finished_at=CASE WHEN remaining THEN NULL ELSE now() END,lease_until=CASE WHEN remaining THEN now()+interval '10 seconds' ELSE NULL END,lease_id=NULL WHERE id=p_job; RETURN true; END; $$; REVOKE ALL ON FUNCTION public.finish_celo_batch(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.finish_celo_batch(uuid,uuid) TO service_role;
CREATE FUNCTION public.tick_celo_batch() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,cron,net AS $$ DECLARE secret text; n integer; count_jobs integer; BEGIN SELECT count(*) INTO count_jobs FROM public.celo_batch_jobs WHERE status IN ('running','stopping'); IF count_jobs=0 THEN PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname='celo-batch-active'; RETURN; END IF; SELECT token INTO secret FROM public.gd_collection_callback_config WHERE id=true; IF secret IS NULL THEN RETURN; END IF; FOR n IN 1..least(count_jobs,10) LOOP PERFORM net.http_post(url:='https://project--dd2e3899-be18-40bc-be79-18eb1f70fcff.lovable.app/api/public/hooks/celo-batch',headers:=jsonb_build_object('Content-Type','application/json','x-collection-token',secret),body:='{}'::jsonb,timeout_milliseconds:=55000); END LOOP; END; $$; REVOKE ALL ON FUNCTION public.tick_celo_batch() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.tick_celo_batch() TO service_role;
CREATE FUNCTION public.wake_celo_batch() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,cron,net AS $$ BEGIN PERFORM cron.schedule('celo-batch-active','* * * * *',$cmd$ SELECT public.tick_celo_batch(); $cmd$); RETURN NEW; END; $$; REVOKE ALL ON FUNCTION public.wake_celo_batch() FROM PUBLIC; CREATE TRIGGER celo_batch_wake AFTER INSERT ON public.celo_batch_jobs FOR EACH ROW EXECUTE FUNCTION public.wake_celo_batch();
COMMENT ON TABLE public.gd_bulk_jobs IS 'DEPRECATED: G$ bulk sending replaced by native CELO batches; existing historical data retained.'; COMMENT ON TABLE public.gd_bulk_recipients IS 'DEPRECATED: replaced by celo_batch_chunks; existing historical data retained.';